from django.contrib.auth.decorators import permission_required
from django.shortcuts import redirect, render
from .forms import CentreForm

@permission_required("centres.add_centre", raise_exception=True)
def creer(request):
    if request.method == "POST":
        form = CentreForm(request.POST)
        if form.is_valid():
            centre = form.save()
            return redirect("centres:detail", pk=centre.pk)
    else:
        form = CentreForm()
    return render(request, "centres/formulaire.html", {"form": form})

