from django.contrib.auth.decorators import permission_required
from django.shortcuts import get_object_or_404, redirect, render
from .forms import CentreForm
from .models import Centre

@permission_required("centres.change_centre", raise_exception=True)
def modifier(request, pk):
    centre = get_object_or_404(Centre, pk=pk)
    if request.method == "POST":
        form = CentreForm(request.POST, instance=centre)
        if form.is_valid():
            form.save()
            return redirect("centres:detail", pk=centre.pk)
    else:
        form = CentreForm(instance=centre)
    return render(
        request, "centres/formulaire.html",
        {"form": form, "centre": centre},
    )

from django.contrib.auth.decorators import permission_required
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_http_methods
from .models import Centre

@permission_required("centres.delete_centre", raise_exception=True)
@require_http_methods(["GET", "POST"])
def supprimer(request, pk):
    centre = get_object_or_404(Centre, pk=pk)
    if request.method == "POST":
        centre.delete()
        return redirect("centres:accueil")
    return render(
        request, "centres/confirmer_suppression.html",
        {"centre": centre},
    )

